#!/usr/bin/env python3
# Flugfunk-4: Karte, Saetze, Guard, Watchdog. Kein Mesh. prepper-sdr bleibt.
from __future__ import annotations
import base64, hashlib, json, os, shutil, sys
from datetime import datetime
from pathlib import Path

DASH = Path("/home/fmg/prepper-dashboard")
DATEIEN = ("flugfunk.py", "dashboard.py")
FEST = {
    "flugfunk.py": ("3378b1c585806af8", 69509),
    "prepper_sdr.py": ("9519012e7a1142ba", 779574),
}
PAKETE = """===== SCHRITT PAKETE, dieses Skript installiert nichts =====
rtl_airband bleibt /usr/local/bin/rtl_airband (Quellbau, -DSOAPYSDR=OFF -DPULSEAUDIO=OFF).
===== ENDE SCHRITT PAKETE ====="""

def load():
    return json.loads(PAYLOAD_TEXT)

def sha(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()

def fenster(now=None):
    from zoneinfo import ZoneInfo
    jetzt = now or datetime.now(ZoneInfo("Europe/Berlin"))
    return 5 <= jetzt.minute <= 39, "Berlin Minute %02d" % jetzt.minute

def paare():
    roh = load()["pairs"]
    return {name: [(base64.b64decode(x["old"]), base64.b64decode(x["new"])) for x in roh[name]] for name in DATEIEN}

def verwandle(data, pairs):
    neu = data
    for old, neu_s in pairs:
        if neu.count(neu_s) >= 1 and neu.count(old) == 0:
            continue
        if neu.count(old) != 1 or neu.count(neu_s) != 0 or old in neu_s:
            raise RuntimeError("Stelle")
        vor = neu
        neu = neu.replace(old, neu_s, 1)
        if neu.replace(neu_s, b"", 1) != vor.replace(old, b"", 1):
            raise RuntimeError("ausserhalb")
    return neu

def sichern(path: Path, data: bytes):
    stempel = datetime.now().astimezone().strftime("%Y%m%dT%H%M%S")
    alt = sorted(path.parent.glob(path.name + ".bak-flugfunk4-*"))
    bak = path.with_name(path.name + ".bak-flugfunk4-" + stempel)
    shutil.copy2(path, bak)
    if bak.read_bytes() != data:
        bak.unlink()
        raise RuntimeError("Sicherung")
    for alt_pfad in alt[:-2]:
        try:
            alt_pfad.unlink()
        except OSError:
            pass

def schreiben(path: Path, data: bytes):
    mode = path.stat().st_mode & 0o777
    tmp = path.with_name("." + path.name + ".tmp-flugfunk4")
    if tmp.exists():
        raise RuntimeError("temporaer")
    try:
        with open(tmp, "wb") as handle:
            handle.write(data)
            handle.flush()
            os.fsync(handle.fileno())
        os.chmod(tmp, mode)
        os.replace(tmp, path)
    finally:
        if tmp.exists():
            try:
                tmp.unlink()
            except OSError:
                pass

def apply_dir(ordner: Path, dry: bool, kein: bool, jetzt=None, hashcheck=True) -> int:
    print(PAKETE)
    liste = paare()
    blobs = {}
    for name in ("flugfunk.py", "dashboard.py", "prepper_sdr.py"):
        pfad = ordner / name
        if not hashcheck and name == "prepper_sdr.py" and not pfad.is_file():
            continue
        if pfad.is_symlink() or not pfad.is_file():
            print("STOP: %s fehlt" % name)
            return 2
        data = pfad.read_bytes()
        blobs[name] = data
        print("%s sha16 %s bytes %d" % (name, sha(data)[:16], len(data)))
        if hashcheck and name in FEST:
            kopf, laenge = FEST[name]
            if not sha(data).startswith(kopf) or len(data) != laenge:
                print("STOP: %s ist nicht der Stand nach apply-flugfunk-3" % name)
                return 2
    try:
        ziel = {name: verwandle(blobs[name], liste[name]) for name in DATEIEN}
    except RuntimeError:
        print("STOP: Stelle unbekannt")
        return 2
    if hashcheck:
        for name, data in ziel.items():
            compile(data, name, "exec")
    if b"wach_text" not in ziel["flugfunk.py"] or b"Notfrequenz Guard" not in ziel["flugfunk.py"]:
        print("STOP: Ausbau fehlt")
        return 2
    if b"wach_text" not in ziel["dashboard.py"]:
        print("STOP: Watchdog-Text fehlt")
        return 2
    for name in DATEIEN:
        print("%s endstand sha16 %s bytes %d" % (name, sha(ziel[name])[:16], len(ziel[name])))
    if all(blobs[name] == ziel[name] for name in DATEIEN):
        print("bereits installiert, keine Aenderung, kein Neustart")
        return 0
    frei, meldung = fenster(jetzt)
    print(meldung)
    if dry:
        print("DRY-RUN: kein Backup, kein Schreiben, kein Neustart")
        return 0
    if not frei:
        print("STOP: Neustart nur Minute 05-39 Berlin. Nichts geschrieben.")
        return 2
    try:
        for name in DATEIEN:
            sichern(ordner / name, blobs[name])
            schreiben(ordner / name, ziel[name])
    except (OSError, RuntimeError):
        print("STOP beim Schreiben")
        return 3
    print("geschrieben. prepper-sdr bleibt laufen.")
    if kein or ordner != DASH:
        print("Kein Neustart in dieser Pruefung.")
        return 0
    frei, meldung = fenster()
    print(meldung)
    if not frei:
        print("STOP: Dateien sind neu, der Neustart bleibt aus.")
        return 2
    __import__("subprocess").run(["systemctl", "restart", "prepper-dashboard.service"], check=False)
    print("Nur prepper-dashboard neu gestartet.")
    return 0

def selftest() -> int:
    assert fenster(datetime(2026, 11, 21, 12, 5))[0] and not fenster(datetime(2026, 11, 21, 12, 4))[0]
    import tempfile
    ordner = Path(tempfile.mkdtemp(prefix="flugfunk4-"))
    (ordner / "flugfunk.py").write_bytes(b"UNBERUEHRT")
    (ordner / "dashboard.py").write_bytes(b"UNBERUEHRT")
    assert apply_dir(ordner, True, True, datetime(2026, 11, 21, 12, 12), False) == 2
    liste = paare()
    for name, pairs in liste.items():
        (ordner / name).write_bytes(b"\n".join(old for old, _n in pairs))
    assert apply_dir(ordner, False, True, datetime(2026, 11, 21, 12, 40), False) == 2
    assert (ordner / "flugfunk.py").read_bytes().startswith(b"UNBERUEHRT") or b"wach_text" not in (ordner / "flugfunk.py").read_bytes()[:20]
    assert apply_dir(ordner, False, True, datetime(2026, 11, 21, 12, 12), False) == 0
    roh = base64.b64decode(load()["flugfunk_neu"])
    ns = {"__name__": "flugfunk"}
    exec(compile(roh, "flugfunk.py", "exec"), ns)
    adsb = ns["funk_seite"]("<html><body></body></html>", "/adsb")
    funk = ns["funk_seite"](adsb, "/funk")
    assert ns["fullcheck_blatt"]("/adsb", adsb) == ""
    assert ns["fullcheck_blatt"]("/funk", funk) == ""
    assert "ffKarte" in adsb and "ffZeit" in adsb and "ffWetter" in adsb
    zeile = ns["wach_text"]("Stick 3 · Hobby: RDS ok · nur Beobachtung · von Stick 2 · Hobby", {"kopf": "121,500 MHz · Notfrequenz Guard"})
    assert zeile.startswith("Stick 3 · Flugfunk:") and "RDS" not in zeile and "von Stick 2" not in zeile
    assert "/api/flugfunk" in ns["SOLL_APIS"] and "/adsb" in ns["SOLL_SEITEN"] and "/funk" in ns["SOLL_SEITEN"]
    print("selftest ok")
    return 0

def main(argv):
    args = argv[1:]
    dry = kein = False
    wurzel = DASH
    i = 0
    while i < len(args):
        a = args[i]
        if a == "--dry-run":
            dry = True
        elif a == "--kein-neustart":
            kein = True
        elif a == "--selftest":
            return selftest()
        elif a == "--wurzel":
            i += 1
            wurzel = Path(args[i])
        else:
            print("STOP: unbekanntes Argument")
            return 2
        i += 1
    return apply_dir(wurzel, dry, kein)

